TEST_CASE("encode_sw: known encodings (golden hex from riscv64-elf-as)")
{
    // sw rs2, imm(rs1): STORE opcode 0x23, funct3=010 (32-bit). Same S-type shape
    // as encode_sd but a word store -- L2C MMIO registers must be accessed < 8
    // bytes at a time (DS220 11.8.3), so the L2C config restore writes a word.
    // Verified with `riscv64-elf-as`.
    CHECK(encode_sw(5, 6, 8)     == 0x00532423u);  // sw x5,8(x6)
    CHECK(encode_sw(5, 6, 0)     == 0x00532023u);  // sw x5,0(x6)
    CHECK(encode_sw(31, 30, 2047) == 0x7FFF2FA3u); // sw x31,2047(x30) (max imm)
}

TEST_CASE("encode_lwu: known encodings (golden hex from riscv64-elf-as)")
{
    // lwu rd, imm(rs1): LOAD opcode 0x03, funct3=110 (32-bit, ZERO-extend). Same
    // I-type shape as encode_ld but a zero-extending word load, so a 32-bit L2C
    // register read does not sign-pollute the upper bits of the u64 it lands in.
    // Verified with `riscv64-elf-as`.
    CHECK(encode_lwu(5, 6, 8)    == 0x00836283u);  // lwu x5,8(x6)
    CHECK(encode_lwu(5, 6, 0)    == 0x00036283u);  // lwu x5,0(x6)
    CHECK(encode_lwu(7, 31, 240) == 0x0F0FE383u);  // lwu x7,240(x31)
}

