27	int main() {
28	  // --- parse_size: <number>[K|M|G|T] -> byte count ---
29	  {
30	    std::string err;
31	    CHECK(parse_size("1024", err) == 1024 && err.empty());
32	    CHECK(parse_size("128M", err) == 128LL * 1024 * 1024);
33	    CHECK(parse_size("512M", err) == 512LL * 1024 * 1024);
34	    CHECK(parse_size("8G", err) == 8LL * 1024 * 1024 * 1024);
35	    CHECK(parse_size("1T", err) == 1LL * 1024 * 1024 * 1024 * 1024);
36	    // fractional value truncates like Python int(float(num) * mult)
37	    CHECK(parse_size("1.5G", err) ==
38	          static_cast<long long>(1.5 * 1024 * 1024 * 1024));
39	    // suffix is case-insensitive and surrounding whitespace is tolerated
40	    CHECK(parse_size("  64m  ", err) == 64LL * 1024 * 1024);
41	    // malformed specs return 0 and set err
42	    for (const char* bad : {"", "8X", "0", "abc", "-4", "1.2.3"}) {
43	      err.clear();
44	      CHECK(parse_size(bad, err) == 0 && !err.empty());
45	    }
46	  }
47	
48	  // --- L26/F2: the physical shared mmap reserves one V-scratch page ABOVE the
49	  //     program's --mem-size, so the scratch sits past the program's declared
50	  //     RAM (scheme D: no program layout can collide). ---
51	  {
52	    CHECK(physical_mmap_bytes(128LL * 1024 * 1024)
53	          == 128LL * 1024 * 1024 + HYBRID_V_SCRATCH_BYTES);
54	    CHECK(physical_mmap_bytes(0) == HYBRID_V_SCRATCH_BYTES);
55	    // The largest --mem-size keeps physical within the 2 GiB AE350 DRAM window.
56	    CHECK(max_program_mem_bytes()
57	          == 2LL * 1024 * 1024 * 1024 - HYBRID_V_SCRATCH_BYTES);
58	    // A program exactly at the cap maps the full DRAM window, no more.
59	    CHECK(physical_mmap_bytes(max_program_mem_bytes())
60	          == 2LL * 1024 * 1024 * 1024);
61	  }
62	
63	  // --- resolve_mmap_dir: first-fit over backing-store tiers ---
64	  {
65	    const long long kFit = 1024 + kMmapSafetyMargin;  // exactly enough
66	    std::vector<MmapTier> tiers = {{"/shm", "/dev/shm"},
67	                                   {"/cache", "~/.cache/andesim"}};
68	    std::string err;
69	
70	    // tier 1 fits -> chosen, no fallback note
71	    {
72	      auto probe = [&](const std::string&) -> long long { return kFit; };
73	      MmapDirChoice c = resolve_mmap_dir(tiers, 1024, probe, err);
74	      CHECK(c.dir == "/shm" && c.note.empty() && err.empty());
75	    }
76	    // tier 1 too small -> tier 2 with a note naming tier 1 and its free space
