81	      MmapDirChoice c = resolve_mmap_dir(tiers, 1024, probe, err);
82	      CHECK(c.dir == "/cache" && err.empty());
83	      CHECK(c.note.find("/dev/shm") != std::string::npos);
84	      CHECK(c.note.find("too small") != std::string::npos);
85	    }
